using Microsoft.VisualStudio.TestTools.UnitTesting;
using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class ChargeAsyncTests
{
    private Payments.PaymentGateway _sut = null!;

    [TestInitialize]
    public void Setup()
    {
        _sut = new Payments.PaymentGateway();
    }

    // ── Happy-path ──────────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidTokenAndPositiveAmount_ReturnsSuccessfulResult()
    {
        // Arrange
        const string cardToken = "tok_valid_visa";
        const decimal amount = 49.99m;

        // Act & Assert – method currently throws NotImplementedException
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    [TestMethod]
    public async Task ChargeAsync_ValidToken_ChargeIdIsNonEmpty()
    {
        // Arrange
        const string cardToken = "tok_mastercard";
        const decimal amount = 100.00m;

        // Act & Assert – once implemented, ChargeId must be non-null/non-empty
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    [TestMethod]
    public async Task ChargeAsync_ValidToken_SuccessIsTrue()
    {
        // Arrange
        const string cardToken = "tok_amex";
        const decimal amount = 25.50m;

        // Act & Assert – once implemented, Success must be true for valid input
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    // ── Edge cases: amount boundaries ───────────────────────────────

    [TestMethod]
    [DataRow("tok_min", 0.01, DisplayName = "Minimum positive amount (0.01)")]
    [DataRow("tok_one", 1.00, DisplayName = "One dollar")]
    [DataRow("tok_cents", 0.99, DisplayName = "Sub-dollar amount")]
    public async Task ChargeAsync_SmallPositiveAmounts_DoesNotThrowArgumentException(
        string cardToken, double amountDouble)
    {
        // Arrange
        decimal amount = (decimal)amountDouble;

        // Act & Assert – should not reject valid small amounts;
        // currently throws NotImplementedException (not ArgumentException)
        var ex = await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
        Assert.IsNotNull(ex);
    }

    [TestMethod]
    public async Task ChargeAsync_VeryLargeAmount_DoesNotThrowArgumentException()
    {
        // Arrange
        const string cardToken = "tok_large";
        const decimal amount = 999_999_999.99m;

        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ThrowsArgumentException()
    {
        // Arrange
        const string cardToken = "tok_zero";
        const decimal amount = 0m;

        // Act & Assert – zero is not a valid charge amount;
        // once implemented this should throw ArgumentException.
        // For now, NotImplementedException is thrown first.
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    // ── Error cases: invalid card token ─────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_NullCardToken_ThrowsArgumentException()
    {
        // Arrange
        const decimal amount = 10.00m;

        // Act & Assert – null token should be rejected;
        // currently throws NotImplementedException before validation
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(null!, amount));
    }

    [TestMethod]
    [DataRow("", DisplayName = "Empty string token")]
    [DataRow("   ", DisplayName = "Whitespace-only token")]
    public async Task ChargeAsync_EmptyOrWhitespaceToken_ThrowsArgumentException(
        string cardToken)
    {
        // Arrange
        const decimal amount = 10.00m;

        // Act & Assert – empty/whitespace tokens should be rejected
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    // ── Error cases: negative amount ────────────────────────────────

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Negative penny")]
    [DataRow(-100.00, DisplayName = "Negative hundred")]
    [DataRow(-999999.99, DisplayName = "Large negative amount")]
    public async Task ChargeAsync_NegativeAmount_ThrowsArgumentException(
        double amountDouble)
    {
        // Arrange
        const string cardToken = "tok_neg";
        decimal amount = (decimal)amountDouble;

        // Act & Assert – negative amounts should be rejected;
        // currently throws NotImplementedException before validation
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }
}

